package integration_test
import("context";"testing";"time";"github.com/vance1852/foodsafe-traceability/internal/permit")
func TestPermitCreateRollsBackWhenAuditFails(t *testing.T){f:=newFixture(t);g:=f.createSourceGraph(t);now:=time.Now().UTC();if _,err:=f.store.DB().Exec(`CREATE TRIGGER fail_permit_create_audit BEFORE INSERT ON audit_events WHEN NEW.action = 'permit.create' BEGIN SELECT RAISE(ABORT, 'audit sink unavailable'); END`);err!=nil{t.Fatal(err)};_,err:=f.permits.Create(context.Background(),f.supervisor,permit.CreateCommand{FacilityID:g.source.ID,HolderName:"Plant",Reference:"PRIVATE-CREATE",ValidFrom:now.Add(-time.Hour),ValidUntil:now.Add(time.Hour),DailyVolumeLimitLiters:1000,RequestID:"private-create-failing"});if err==nil{t.Fatal("create unexpectedly succeeded")};var count int;if err=f.store.DB().QueryRow(`SELECT COUNT(*) FROM permits WHERE reference='PRIVATE-CREATE'`).Scan(&count);err!=nil{t.Fatal(err)};if count!=0{t.Fatalf("failed create persisted %d permits",count)};if _,err=f.store.DB().Exec(`DROP TRIGGER fail_permit_create_audit`);err!=nil{t.Fatal(err)};_,err=f.permits.Create(context.Background(),f.supervisor,permit.CreateCommand{FacilityID:g.source.ID,HolderName:"Plant",Reference:"PRIVATE-CREATE",ValidFrom:now.Add(-time.Hour),ValidUntil:now.Add(time.Hour),DailyVolumeLimitLiters:1000,RequestID:"private-create-retry"});if err!=nil{t.Fatal(err)}}
